SELECT sessions.id, sessions.country, t.cart_count, t.checkout_count FROM sessions INNER JOIN (SELECT session_id, SUM(CASE WHEN page = '/cart' THEN 1 ELSE 0 END) AS cart_count, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count FROM web_events WHERE TO_DATE(event_time) >= '2024-08-01' GROUP BY session_id) t ON sessions.id = t.session_id ORDER BY id DESC, sessions.country;
